// LAB: Classify termination before reading its value
// Use a tagged status model for normal exit and signal termination. Do not interpret a signal number as an exit code.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <optional>

int main() {
    std::optional<int> child_status = 7;
    assert(child_status.has_value());
    const int exit_code = *child_status;
    child_status.reset();
    std::cout << "exit=" << exit_code << " reaped=" << std::boolalpha
              << !child_status.has_value() << '\n';
}

#include <cassert>
#include <iostream>
#include <string>

enum class Termination { Exited, Signaled };
struct Status { Termination kind; int value; };
std::string describe(Status status) {
    return (status.kind == Termination::Exited ? "exit=" : "signal=") + std::to_string(status.value);
}

int main() {
    assert(describe({Termination::Exited,7}) == "exit=7");
    assert(describe({Termination::Signaled,15}) == "signal=15");
    std::cout << describe({Termination::Exited,7}) << ' ' << describe({Termination::Signaled,15}) << '\n';
}
